function draw(){ctx.clearRect(0,0,W,H);if(state.scene==='apartment')drawApartment();else if(state.scene==='street')drawStreet();else drawFoundry();if(state.scene==='foundry')$('bossHealth').style.width=state.boss+'%'}
function frame(t){const dt=Math.min(.04,(t-(state.last||t))/1000);state.last=t;state.anim+=dt;if(state.toastTimer>0){state.toastTimer-=dt;if(state.toastTimer<=0)$('toast').classList.remove('show')}if(state.started&&!state.dialogue){const dx=(state.keys.right?1:0)-(state.keys.left?1:0),dy=(state.keys.down?1:0)-(state.keys.up?1:0),mag=Math.hypot(dx,dy)||1;state.player.x+=dx/mag*175*dt;state.player.y+=dy/mag*145*dt;state.player.x=Math.max(26,Math.min(928,state.player.x));state.player.y=Math.max(402,Math.min(485,state.player.y));if(state.attackCd>0)state.attackCd=Math.max(0,state.attackCd-dt);if(state.scene==='foundry'&&!state.defeated){state.bossSlow=Math.max(0,state.bossSlow-dt);state.bossTimer+=dt;if(state.bossTimer>=(state.bossSlow>0?3.5:2.4)){state.bossTimer=0;if(Math.abs(state.player.x-750)<240){const damage=state.power==='ice'?7:state.power==='crystal'?3:12;state.hp-=damage;$('statusHint').textContent=`ROWAN · ${state.hp}% VITALITY`;toast(state.power==='crystal'?'CRYSTAL GUARD softens the shockwave.':'Viktor’s shards hit you—move or change aspect!');if(state.hp<=0){state.hp=100;state.player.x=130;toast('You retreat, catch your breath, and return.')}}}}}draw();requestAnimationFrame(frame)}
function startGame(){state.started=true;$('intro').style.display='none';toast('CASE OPEN · Find Mara and search the apartment');canvas.focus?.()}
function setMove(direction,on){state.keys[direction]=on}
