(()=>{'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const $=id=>document.getElementById(id), W=960,H=540;
const state={started:false,scene:'apartment',player:{x:140,y:430},power:'fire',rel:0,talked:false,glass:false,note:false,doorUnlocked:false,combat:false,boss:100,hp:100,attackCd:0,defeated:false,ended:false,dialogue:false,toastTimer:0,anim:0,keys:{},sound:true,bossSlow:0,bossTimer:0};
const scenes={apartment:{label:'NORTHLINE · 11:42 PM',chapter:'CHAPTER I — THE QUIET ROOM',title:'A home under glass',objective:'Speak with Mara, then search the apartment for evidence.'},street:{label:'NORTHLINE · CINDERBLOCK ROW',chapter:'CHAPTER II — COLD TRAIL',title:'The city keeps score',objective:'Follow the trail to Vale Ironworks. Head east.'},foundry:{label:'NORTHLINE · VALE IRONWORKS',chapter:'CHAPTER III — THE SHARD',title:'A reckoning in steel',objective:'Stop Viktor. Watch for his crystal shockwaves.'}};
const aspectColor={fire:'#ff9d52',ice:'#83d9ec',crystal:'#e5a2e8'};
function toast(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');state.toastTimer=2.6}
function setScene(scene){state.scene=scene;state.player=scene==='apartment'?{x:140,y:430}:scene==='street'?{x:110,y:434}:{x:100,y:433};$('sceneLabel').textContent=scenes[scene].label;$('chapter').textContent=scenes[scene].chapter;$('chapterTop').textContent=scenes[scene].chapter.replace(/^CHAPTER [I]+ — /,'').toUpperCase();$('sideTitle').textContent=scenes[scene].title;$('objective').textContent=scenes[scene].objective;$('progress').style.width=scene==='apartment'?'18%':scene==='street'?'60%':'82%';$('combatUI').style.display=scene==='foundry'?'block':'none';$('statusHint').textContent=scene==='foundry'?`ROWAN · ${state.hp}% VITALITY`:'CASE FILE · ROWAN VALE'}
function setRel(amount){state.rel=Math.max(-4,Math.min(4,state.rel+amount));$('relValue').textContent=`${state.rel>0?'+':''}${state.rel} / 4`;$('relMeter').style.width=`${((state.rel+4)/8)*100}%`;$('relHint').textContent=state.rel<=-3?'The marriage is close to breaking.':state.rel<0?'Mara is tired of being shut out.':state.rel>=3?'You are finding your way back to each other.':'A fragile truce. Words still matter.'}
function foundClue(key){state[key]=true;const id=key==='talked'?'talk':key;$('clue-'+id)?.classList.add('found');const item=$('clue-'+id);if(item)item.querySelector('b').textContent='✓';if(state.talked&&state.glass&&state.note){state.doorUnlocked=true;$('objective').textContent='The clues point to Vale Ironworks. Head out through the front door.';$('progress').style.width='45%';toast('CASE UPDATED · Vale Ironworks identified')}}
function openDialogue(speaker,text,options){state.dialogue=true;$('speaker').textContent=speaker;$('dialogueText').textContent=text;const list=$('choices');list.replaceChildren();for(const option of options){const button=document.createElement('button');button.className='choice';button.textContent=option.text;button.onclick=()=>{option.action?.();if(option.next)openDialogue(option.next.speaker,option.next.text,option.next.options);else closeDialogue()};list.append(button)}$('dialogue').style.display='block'}
function closeDialogue(){state.dialogue=false;$('dialogue').style.display='none'}
function talkMara(){if(!state.talked){openDialogue('MARA · YOUR WIFE','You’re home. I thought the whole building was going to catch fire again. You said you’d be here for dinner, Rowan.',[
{text:'“You’re right. I’m sorry. Tell me what happened.”  +1',action:()=>{setRel(1);foundClue('talked');toast('Mara noticed you listened. Relationship +1')},next:{speaker:'MARA',text:'Someone came asking for Viktor. He had these glassy hands—like he could bend the streetlights. I heard a crash from the old foundry.',options:[{text:'“Thank you. I’ll be careful—and I’ll come back.”  +1',action:()=>{setRel(1);toast('A promise kept is a start. Relationship +1')}},{text:'“This is bigger than dinner. I have to go.”  −1',action:()=>{setRel(-1);toast('Mara feels brushed aside. Relationship −1')}}]}},
{text:'“Work is dangerous. I’m trying to protect you.”  −1',action:()=>{setRel(-1);foundClue('talked');toast('Mara wants a partner, not a shield. Relationship −1')},next:{speaker:'MARA',text:'Protect me by letting me in. I heard a crash at the old foundry—someone was asking for Viktor.',options:[{text:'“You’re right. I should have told you. Thank you.”  +1',action:()=>{setRel(1);toast('You let her in. Relationship +1')}},{text:'“I don’t have time for this.”  −2',action:()=>{setRel(-2);toast('The distance grows. Relationship −2')}}]}},
{text:'“I’m working. Can this wait?”  −2',action:()=>{setRel(-2);foundClue('talked');toast('Mara feels abandoned. Relationship −2')},next:{speaker:'MARA',text:'It always waits. I heard a crash at the foundry. That’s all I have to say.',options:[{text:'“I’m sorry. I’ll make this right.”  +1',action:()=>{setRel(1);toast('An apology is a beginning. Relationship +1')}},{text:'“Fine. I’m leaving.”  −1',action:()=>{setRel(-1);toast('Mara turns away. Relationship −1')}}]}}
]);return}const intro=state.rel<=-3?'You can chase this case. I can’t keep waiting for you to come back to us.':state.rel>=2?'I left the light on. Just… don’t make me wonder if you’re coming back.':'Be careful out there, Rowan. The foundry is where I heard the crash.';openDialogue('MARA',intro,[{text:'“I’ll come back. We’ll talk properly.”  +1',action:()=>{setRel(1);toast('You made a promise. Relationship +1')}},{text:'“I can’t promise anything.”  −1',action:()=>{setRel(-1);toast('Mara looks away. Relationship −1')}},{text:'“What else did you hear about the intruder?”',next:{speaker:'MARA',text:'Only that Viktor Vale was seen near the ironworks. He used to work there, before the accident.',options:[{text:'“Thank you for trusting me.”  +1',action:()=>{setRel(1);toast('Relationship +1')}},{text:'“That’s all I needed.”',action:()=>{}}]}}])}
function selectPower(power){state.power=power;document.querySelectorAll('.power').forEach(button=>button.classList.toggle('active',button.dataset.power===power));toast(`${power.toUpperCase()} ASPECT`)}
function interact(){if(state.dialogue||!state.started)return;const p=state.player;if(state.scene==='apartment'){if(Math.abs(p.x-423)<92&&Math.abs(p.y-410)<86){talkMara();return}if(!state.glass&&Math.abs(p.x-620)<84&&Math.abs(p.y-420)<90){if(state.power!=='ice'){toast('The shards are brittle. Change to ICE (2) to read the fracture.');return}foundClue('glass');$('objective').textContent=state.talked?'Find the hidden message.':'Speak with Mara, then search for the hidden message.';toast('CLUE FOUND · Glass fractured from within');return}if(!state.note&&Math.abs(p.x-680)<78&&Math.abs(p.y-420)<85){if(state.power!=='crystal'){toast('A faint impression remains. Change to CRYSTAL (3) to reveal it.');return}foundClue('note');toast('CLUE FOUND · Viktor’s address, etched in crystal');return}if(p.x>855){if(state.doorUnlocked){setScene('street');toast('You step into the rain-soaked Northline.')}else toast('Not yet. Speak with Mara and investigate both clues.');return}toast('Nothing new here. Move close to Mara or the evidence.');return}
if(state.scene==='street'){if(p.x>820){setScene('foundry');toast('The ironworks door groans open.');return}if(Math.abs(p.x-480)<115&&Math.abs(p.y-420)<100){toast(state.power==='fire'?'Soot glimmers in the rain. The trail leads east.':state.power==='ice'?'Frozen footprints point east, toward the ironworks.':'A crystal splinter points toward the ironworks.');return}toast('Follow the avenue east toward the old ironworks.');return}
if(state.defeated){if(p.x>810){ending();return}toast('Viktor is down. Walk east to the exit and close the case.');return}if(Math.abs(p.x-750)<155){attack();return}toast('Move close to Viktor and press E or SPACE to strike.')}
function attack(){if(state.attackCd>0){toast('Recovering—keep moving!');return}if(state.power==='fire'){state.boss-=24;state.attackCd=.65;toast('FIRE BURST · Viktor staggers!')}else if(state.power==='ice'){state.boss-=13;state.attackCd=.6;state.bossSlow=3;toast('ICE SHARD · His next attack slows!')}else{state.boss-=18;state.attackCd=.65;state.hp=Math.min(100,state.hp+8);toast('CRYSTAL GUARD · Strike and recover!')}state.boss=Math.max(0,state.boss);$('bossHealth').style.width=state.boss+'%';if(state.boss===0){state.defeated=true;toast('Viktor disarmed. The case is yours.');$('objective').textContent='Walk east to the foundry exit to close the case.';$('progress').style.width='95%'}}
function ending(){if(state.ended)return;state.ended=true;const divorced=state.rel<=-3;const text=divorced?'Viktor is in custody. The city calls you a hero. At home, Mara’s ring rests on the table. She has chosen a life beyond your shadow. The case is closed; your marriage is not.':'Viktor is in custody. The city can sleep. When you get home, Mara is still awake. This time, you sit together in the quiet and let the truth out—one piece at a time.';openDialogue('CASE CLOSED · NORTHLINE',text,[{text:'“Begin again” · Return to the title',action:()=>location.reload()}]);$('progress').style.width='100%'}
function text(s,x,y,size=12,color='#e7dfcc',font='sans-serif',align='left'){ctx.fillStyle=color;ctx.font=`${size}px ${font}`;ctx.textAlign=align;ctx.fillText(s,x,y)}
function prompt(s,x,y){ctx.save();ctx.font='10px monospace';const w=ctx.measureText(s).width+18;ctx.fillStyle='#101719dd';ctx.fillRect(x-w/2,y-17,w,23);ctx.strokeStyle='#c6ad7d';ctx.strokeRect(x-w/2,y-17,w,23);text(s,x,y-2,10,'#f1dfb8','monospace','center');ctx.restore()}
function person(x,y,kind='rowan'){ctx.save();ctx.translate(x,y);const color=kind==='mara'?'#d89b78':'#c68f72',coat=kind==='mara'?'#8a6555':state.power==='fire'?'#a44f35':state.power==='ice'?'#416b78':'#66506f';ctx.fillStyle='#080d0dcc';ctx.beginPath();ctx.ellipse(0,0,20,6,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#211f20';ctx.fillRect(-10,-19,8,19);ctx.fillRect(3,-19,8,19);ctx.fillStyle=coat;ctx.beginPath();ctx.moveTo(-14,-49);ctx.lineTo(13,-49);ctx.lineTo(17,-19);ctx.lineTo(-15,-19);ctx.closePath();ctx.fill();ctx.fillStyle='#d9c8ac';ctx.fillRect(-4,-47,8,17);ctx.fillStyle=color;ctx.beginPath();ctx.arc(0,-59,11,0,Math.PI*2);ctx.fill();ctx.fillStyle=kind==='mara'?'#40292a':'#2c2523';ctx.beginPath();ctx.arc(0,-63,12,Math.PI,Math.PI*2);ctx.fill();if(kind==='rowan'){ctx.fillStyle=aspectColor[state.power];ctx.globalAlpha=.72;ctx.beginPath();ctx.arc(0,-37,23+Math.sin(state.anim*6)*2,Math.PI,Math.PI*2);ctx.strokeStyle=aspectColor[state.power];ctx.lineWidth=2;ctx.stroke();ctx.globalAlpha=1}ctx.restore()}
